@import "@fontsource-variable/inter";
@import "tailwindcss";

@theme {
  --font-sans: "Inter Variable", Inter, ui-sans-serif, system-ui, sans-serif;
  --color-ink: #0f172a;
  --color-ink-2: #475569;
  --color-ink-3: #64748b;
  --color-line: #e2e8f0;
  --color-panel: #f8fafc;
  --color-ok: #1d6fe0;
  --color-warn: #d97706;
  --color-stop: #dc2626;
  --color-silent: #7b8494;
  --color-land: #eceff3;
}

html, body, #root { height: 100%; }
body {
  background: #fff;
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-feature-settings: "tnum" 1, "cv11" 1;
  -webkit-font-smoothing: antialiased;
}

@keyframes pulse-ring {
  0% { r: 5px; opacity: .9; }
  100% { r: 20px; opacity: 0; }
}
.pulse-ring { animation: pulse-ring 1.6s ease-out infinite; }
.pulse-once { animation: pulse-ring 1.2s ease-out 3; }
.pulse-once.delay { animation-delay: .5s; }

@keyframes recolour {
  0% { stroke-width: 7px; }
  100% { stroke-width: 2.75px; }
}
.route-recolour { animation: recolour 1.2s ease-out; }

@keyframes slide-in {
  from { opacity: 0; transform: translateY(-14px); }
  to { opacity: 1; transform: none; }
}
.slide-in { animation: slide-in .45s ease-out; }

@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, -8px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}
.toast-in { animation: toast-in .25s ease-out; }
